CREATE TABLE ReturnRequest (id VARCHAR(191) NOT NULL PRIMARY KEY,orderId VARCHAR(191) NOT NULL,items JSON NOT NULL,reason VARCHAR(191) NOT NULL,state VARCHAR(191) NOT NULL DEFAULT 'PENDING',requestedBy VARCHAR(191) NOT NULL,decisionReason VARCHAR(191) NOT NULL DEFAULT '',decidedBy VARCHAR(191) NULL,decidedAt DATETIME(3) NULL,goodsReceived BOOLEAN NOT NULL DEFAULT false,restocked BOOLEAN NOT NULL DEFAULT false,refundAmount INTEGER NOT NULL DEFAULT 0,refundReference VARCHAR(191) NULL,refundNote VARCHAR(191) NULL,refundedBy VARCHAR(191) NULL,refundedAt DATETIME(3) NULL,createdAt DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),UNIQUE KEY ReturnRequest_refundReference_key(refundReference),INDEX ReturnRequest_orderId_state_idx(orderId,state),CONSTRAINT ReturnRequest_orderId_fkey FOREIGN KEY(orderId) REFERENCES `Order`(id) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
